// app/api/notifications/pending-core-count/route.ts
import { NextResponse, NextRequest } from 'next/server'
import { createUserClient } from '@/lib/supabase/server'

export async function GET(_req: NextRequest) {
  const supabase = await createUserClient()

  const { data: userData } = await supabase.auth.getUser()
  const user = userData.user
  if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  // オーナーのルーム一覧
  const { data: rooms, error: roomsErr } = await supabase
    .from('rooms')
    .select('id')
    .eq('created_by', user.id)

  if (roomsErr) return NextResponse.json({ error: '処理できませんでした。時間をおいてお試しください' }, { status: 400 })

  const roomIds = (rooms ?? []).map((r) => r.id)
  if (roomIds.length === 0) {
    return NextResponse.json({ count: 0 })
  }

  // pending core 申請数
  const { count, error: countErr } = await supabase
    .from('room_join_requests')
    .select('id', { count: 'exact', head: true })
    .in('room_id', roomIds)
    .eq('requested_role', 'core')
    .eq('status', 'pending')

  if (countErr) return NextResponse.json({ error: '処理できませんでした。時間をおいてお試しください' }, { status: 400 })

  return NextResponse.json({ count: count ?? 0 })
}

// app/api/posts/delete/route.ts
import { NextResponse } from 'next/server'
import { supabaseAdmin } from '../../../../lib/supabase/admin'

export const dynamic = 'force-dynamic'

export async function POST(req: Request) {
  try {
    // --- auth ---
    const auth = req.headers.get('authorization') ?? ''
    const token = auth.startsWith('Bearer ') ? auth.slice(7) : null
    if (!token) return NextResponse.json({ ok: false, error: 'Unauthorized' }, { status: 401 })

    const { data: userRes, error: userErr } = await supabaseAdmin.auth.getUser(token)
    if (userErr || !userRes.user) {
      return NextResponse.json({ ok: false, error: 'Unauthorized' }, { status: 401 })
    }
    const user = userRes.user

    // --- body ---
    const body = await req.json().catch(() => ({}))
    const postId = String(body.postId ?? '').trim()
    if (!postId) return NextResponse.json({ ok: false, error: 'postId is required' }, { status: 400 })

    // 1) 投稿取得（所有者チェック）
    const { data: post, error: postErr } = await supabaseAdmin
      .from('posts')
      .select('id, room_id, user_id, deleted_at')
      .eq('id', postId)
      .maybeSingle()

    if (postErr || !post) {
      return NextResponse.json({ ok: false, error: 'post not found' }, { status: 404 })
    }

    // 既に削除済みならOK
    if (post.deleted_at) {
      return NextResponse.json({ ok: true })
    }

    // ✅ 他人の投稿は絶対に不可
    if (post.user_id !== user.id) {
      return NextResponse.json({ ok: false, error: 'forbidden' }, { status: 403 })
    }

    // 2) ルーム確認（open以外は操作不可：安全側）
    const { data: room, error: roomErr } = await supabaseAdmin
      .from('rooms')
      .select('id, status, is_hidden, deleted_at')
      .eq('id', post.room_id)
      .maybeSingle()

    if (roomErr) return NextResponse.json({ ok: false, error: '処理できませんでした。時間をおいてお試しください' }, { status: 500 })
    if (!room || room.is_hidden !== false || room.deleted_at != null) return NextResponse.json({ ok: false, error: 'room not found' }, { status: 404 })
    if (room.status !== 'open') {
      return NextResponse.json(
        { ok: false, error: `このルームは ${room.status} のため操作できません` },
        { status: 403 }
      )
    }

    // 3) ✅ 参加者チェック（投稿者本人でも、参加から抜けてたら不可）
    const { data: mem, error: memErr } = await supabaseAdmin
      .from('room_members')
      .select('id')
      .eq('room_id', post.room_id)
      .eq('user_id', user.id)
      .is('left_at', null)
      .maybeSingle()

    if (memErr) return NextResponse.json({ ok: false, error: '処理できませんでした。時間をおいてお試しください' }, { status: 500 })
    if (!mem) {
      return NextResponse.json(
        { ok: false, error: 'ルームに参加してから操作してください' },
        { status: 403 }
      )
    }

    // 4) 論理削除（deleted_at を now）
    const { error: updErr } = await supabaseAdmin
      .from('posts')
      .update({ deleted_at: new Date().toISOString() })
      .eq('id', postId)
      .eq('user_id', user.id) // 二重ガード

    if (updErr) {
      return NextResponse.json({ ok: false, error: '処理できませんでした。時間をおいてお試しください' }, { status: 400 })
    }

    return NextResponse.json({ ok: true })
  } catch (e: unknown) {
    return NextResponse.json({ ok: false, error: '処理できませんでした' }, { status: 500 })
  }
}

// app/profile/set-bio/route.ts
import { NextResponse } from 'next/server'
import { supabaseAdmin } from '@/lib/supabase/admin'

export const dynamic = 'force-dynamic'

export async function POST(req: Request) {
  try {
    // Auth (Bearer)
    const auth = req.headers.get('authorization') ?? ''
    const token = auth.startsWith('Bearer ') ? auth.slice(7) : null
    if (!token) {
      return NextResponse.json({ ok: false, error: 'Unauthorized' }, { status: 401 })
    }

    const { data: userRes, error: userErr } = await supabaseAdmin.auth.getUser(token)
    if (userErr || !userRes?.user) {
      return NextResponse.json({ ok: false, error: 'Unauthorized' }, { status: 401 })
    }

    const userId = userRes.user.id

    const body = await req.json().catch(() => ({} as any))
    const raw = typeof body?.bio === 'string' ? body.bio : null

    const trimmed = (raw ?? '').trim()
    const value = trimmed.length === 0 ? null : trimmed

    if (value && value.length > 300) {
      return NextResponse.json({ ok: false, error: '紹介文は300文字以内にしてください' }, { status: 400 })
    }

    // ① profiles 更新
    const { error: upErr } = await supabaseAdmin
      .from('profiles')
      .update({ bio: value })
      .eq('id', userId)

    if (upErr) {
      return NextResponse.json({ ok: false, error: '処理できませんでした。時間をおいてお試しください' }, { status: 400 })
    }

    // ② public_profiles にも反映（存在しない場合は0件更新＝OK）
    const { error: pubErr } = await supabaseAdmin
      .from('public_profiles')
      .update({ bio: value, updated_at: new Date().toISOString() })
      .eq('id', userId)

    if (pubErr) {
      return NextResponse.json({ ok: false, error: '処理できませんでした。時間をおいてお試しください' }, { status: 500 })
    }

    return NextResponse.json({ ok: true })
  } catch {
    return NextResponse.json({ ok: false, error: '処理できませんでした。時間をおいてお試しください' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { supabaseAdmin } from '../../../lib/supabase/admin'

export const dynamic = 'force-dynamic'

export async function POST(req: Request) {
  try {
    const auth = req.headers.get('authorization') ?? ''
    const token = auth.startsWith('Bearer ') ? auth.slice(7) : null
    if (!token) return NextResponse.json({ ok: false, error: 'Unauthorized' }, { status: 401 })

    const { data: userRes, error: userErr } = await supabaseAdmin.auth.getUser(token)
    if (userErr || !userRes.user) return NextResponse.json({ ok: false, error: 'Unauthorized' }, { status: 401 })
    const user = userRes.user

    const body = await req.json().catch(() => ({}))
    const username = String((body as any).username ?? '').trim()

    if (username.length < 2 || username.length > 20) {
      return NextResponse.json({ ok: false, error: 'username must be 2-20 chars' }, { status: 400 })
    }

    // ① profiles 更新（存在しなければ insert、あれば update）
    const { error: upsertErr } = await supabaseAdmin
      .from('profiles')
      .upsert({ id: user.id, username }, { onConflict: 'id' })

    if (upsertErr) {
      return NextResponse.json({ ok: false, error: '処理できませんでした。時間をおいてお試しください' }, { status: 400 })
    }

    // ② public_profiles 同期（username必須なのでここで確実に作る）
    // 既存の公開情報（bio/links/avatar_url）を壊さないために読んで合成
    const { data: pub, error: pubErr } = await supabaseAdmin
      .from('public_profiles')
      .select('bio, links, avatar_url')
      .eq('id', user.id)
      .maybeSingle()

    if (pubErr) {
      return NextResponse.json({ ok: false, error: '処理できませんでした。時間をおいてお試しください' }, { status: 500 })
    }

    const { error: pubUpErr } = await supabaseAdmin.from('public_profiles').upsert(
      {
        id: user.id,
        username,
        bio: (pub?.bio ?? null) as string | null,
        links: (pub?.links ?? null) as any,
        avatar_url: (pub?.avatar_url ?? null) as string | null,
        updated_at: new Date().toISOString(),
      },
      { onConflict: 'id' }
    )

    if (pubUpErr) {
      return NextResponse.json({ ok: false, error: '処理できませんでした。時間をおいてお試しください' }, { status: 500 })
    }

    // ③ 過去投稿の username を一括更新（任意だが体験が良くなる）
    await supabaseAdmin.from('posts').update({ username }).eq('user_id', user.id)

    // ④ 参加者表示も一括更新
    await supabaseAdmin.from('room_members').update({ username }).eq('user_id', user.id)

    return NextResponse.json({ ok: true })
  } catch {
    return NextResponse.json({ ok: false, error: '処理できませんでした。時間をおいてお試しください' }, { status: 500 })
  }
}

'use client'

import Link from 'next/link'
import { useEffect, useState, useCallback, useMemo, useRef } from 'react'
import { supabase } from '../../../lib/supabase/client'

type Role = 'creator' | 'core' | 'supporter' | null

type PostRow = {
  id: string
  user_id: string
  username: string | null
  content: string
  created_at: string
  post_type?: string | null
  deleted_at?: string | null
  attachment_url?: string | null
  attachment_type?: string | null

  is_marked: boolean
  marked_by?: string | null
  marked_at?: string | null
}

export default function BoardClient({
  roomId,
  roomStatus,
  myRole,
}: {
  roomId: string
  roomStatus: string
  myRole: Role
}) {
  const [posts, setPosts] = useState<PostRow[]>([])
  const [error, setError] = useState('')
  const [content, setContent] = useState('')
  const [finalContent, setFinalContent] = useState('')
  const [userId, setUserId] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)

  // ✅ 参加済みか（親からのmyRoleで判定）
  const isMember = !!myRole
  const memberChecked = true

  // ✅ 権限
  const canFinal = myRole === 'core' || myRole === 'creator'
  const isSupporter = myRole === 'supporter'

  const pendingPost = useRef<{ text: string; type: string; file: File | null; requestId: string; uploadId: string | null } | null>(null)

  // 添付（log / final）
  const [logFile, setLogFile] = useState<File | null>(null)
  const [finalFile, setFinalFile] = useState<File | null>(null)

  // signed url cache: postId -> signedUrl
  const [signedMap, setSignedMap] = useState<Record<string, string>>({})

  // ✅ Mark filter
  const [markFilter, setMarkFilter] = useState<'all' | 'marked'>('all')
  const canMark = myRole === 'core' || myRole === 'creator'

  // ✅ iPhone対応：confirm()をやめて自前モーダルにする
  const [confirmTarget, setConfirmTarget] = useState<{ postId: string } | null>(null)
  const [deleting, setDeleting] = useState(false)

  // ✅ ボタン（黒背景＋白文字）スタイル
  const primaryButtonStyle: React.CSSProperties = {
    background: '#111',
    color: '#fff',
    border: '1px solid #111',
    borderRadius: 10,
    padding: '10px 16px',
    fontWeight: 800,
    cursor: 'pointer',
    opacity: loading ? 0.7 : 1,
  }

  const smallButtonStyle: React.CSSProperties = {
    background: '#fff',
    color: '#111',
    border: '1px solid rgba(0,0,0,0.20)',
    borderRadius: 10,
    padding: '6px 10px',
    fontWeight: 900,
    cursor: 'pointer',
  }

  useEffect(() => {
    const init = async () => {
      const { data } = await supabase.auth.getUser()
      const uid = data.user?.id ?? null
      setUserId(uid)
    }
    init()
  }, [])

  const getToken = async () => {
    const session = await supabase.auth.getSession()
    return session.data.session?.access_token ?? null
  }

  // ✅ 入室した瞬間に seen を更新（参加者のみ）
  useEffect(() => {
    const markSeen = async () => {
      try {
        if (!userId) return
        if (!isMember) return
        const token = await getToken()
        if (!token) return

        await fetch('/api/rooms/seen', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ roomId }),
        })
      } catch {
        // 失敗してもUIは壊さない
      }
    }

    markSeen()
  }, [roomId, userId, isMember])

  const fetchPosts = useCallback(async () => {
    const { data, error } = await supabase
      .from('posts')
      .select(
        'id, user_id, username, content, created_at, post_type, deleted_at, attachment_url, attachment_type, is_marked, marked_by, marked_at'
      )
      .eq('room_id', roomId)
      .eq('is_hidden', false)
      .is('deleted_at', null)
      .order('created_at', { ascending: true })

    if (error) {
      setError('投稿を読み込めませんでした。時間をおいてお試しください。')
      return
    }

    setError('')
    const rows = (data ?? []) as PostRow[]
    setPosts(rows)

    const need = rows.filter((p) => p.attachment_url && !signedMap[p.id])
    if (need.length === 0) return

    const token = await getToken()
    if (!token) return

    await Promise.all(
      need.map(async (p) => {
        try {
          const res = await fetch('/api/uploads/sign', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              Authorization: `Bearer ${token}`,
            },
            body: JSON.stringify({ postId: p.id }),
          })
          const json = await res.json()
          if (res.ok && json?.signedUrl) {
            setSignedMap((prev) => ({ ...prev, [p.id]: String(json.signedUrl) }))
          }
        } catch {
          // noop
        }
      })
    )
  }, [roomId, signedMap])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- Starts async I/O; state updates occur after the awaited Supabase query.
    fetchPosts()
    const interval = setInterval(fetchPosts, 5000)
    return () => clearInterval(interval)
  }, [fetchPosts])

  const uploadFile = async (file: File): Promise<{ uploadId: string } | null> => {
    const token = await getToken()
    if (!token) {
      alert('ログインが必要です')
      return null
    }

    const form = new FormData()
    form.append('roomId', roomId)
    form.append('file', file)

    const res = await fetch('/api/uploads', {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}` },
      body: form,
    })

    const json = await res.json()
    if (!res.ok) {
      alert(json?.error ?? 'アップロード失敗')
      return null
    }

    if (typeof json.uploadId !== 'string') throw new Error('添付を確認できませんでした')
    return { uploadId: json.uploadId }
  }

  const submitPost = async (type: 'log' | 'final') => {
    if (roomStatus === 'open' && memberChecked && !isMember) {
      alert('ルームに参加してから投稿してください')
      return
    }

    if (type === 'final' && !canFinal) {
      alert('完成作品ドラフトはcore/creatorのみ投稿できます')
      return
    }

    const text = type === 'log' ? content.trim() : finalContent.trim()
    const file = type === 'log' ? logFile : finalFile

    if (file && file.size > 4_000_000) {
      alert('添付は4MB以下のファイルを選んでください')
      return
    }
    if (text.length > 20000) {
      alert('本文は20000文字以内で入力してください')
      return
    }
    if (!text && !file) {
      alert('本文か添付ファイルのどちらかを入力してください')
      return
    }

    if (roomStatus !== 'open') {
      alert('このルームでは投稿できません')
      return
    }

    setLoading(true)
    try {
    const token = await getToken()
    if (!token) {
      alert('ログインが必要です')
      setLoading(false)
      return
    }

    if (!pendingPost.current || pendingPost.current.text !== text || pendingPost.current.type !== type || pendingPost.current.file !== file) {
      pendingPost.current = { text, type, file, requestId: crypto.randomUUID(), uploadId: null }
    }
    const pending = pendingPost.current
    if (file && !pending.uploadId) {
      const uploaded = await uploadFile(file)
      if (!uploaded) return
      pending.uploadId = uploaded.uploadId
    }
    const res = await fetch('/api/posts/create', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        roomId,
        content: text || '(添付のみ)',
        post_type: type,
        uploadId: pending.uploadId,
        requestId: pending.requestId,
      }),
    })

    const json = await res.json()
    if (!res.ok) {
      alert(json.error ?? '投稿失敗')
      setLoading(false)
      return
    }

    if (type === 'log') {
      setContent('')
      setLogFile(null)
    } else {
      setFinalContent('')
      setFinalFile(null)
    }

    pendingPost.current = null
    await fetchPosts()
    } catch {
      alert('通信に失敗しました。入力を保持しています。再度お試しください。')
    } finally {
      setLoading(false)
    }
  }

  const deletePost = async (postId: string) => {
    if (roomStatus === 'open' && memberChecked && !isMember) {
      alert('ルームに参加してから操作してください')
      return
    }
    setConfirmTarget({ postId })
  }

  const executeDeletePost = async (postId: string) => {
    if (deleting) return
    setDeleting(true)

    try {
      const token = await getToken()
      if (!token) {
        alert('ログインが必要です')
        return
      }

      const res = await fetch('/api/posts/delete', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ postId }),
      })

      const json = await res.json().catch(() => ({}))
      if (!res.ok) {
        alert(json.error ?? '削除失敗')
        return
      }

      await fetchPosts()
    } finally {
      setDeleting(false)
      setConfirmTarget(null)
    }
  }

  const toggleMark = async (postId: string) => {
    if (!canMark) return
    const token = await getToken()
    if (!token) {
      alert('ログインが必要です')
      return
    }

    const before = posts.find((p) => p.id === postId)
    if (!before) return

    const optimisticNext = !before.is_marked
    setPosts((prev) =>
      prev.map((p) =>
        p.id === postId
          ? {
              ...p,
              is_marked: optimisticNext,
              marked_by: optimisticNext ? userId : null,
              marked_at: optimisticNext ? new Date().toISOString() : null,
            }
          : p
      )
    )

    try {
      const res = await fetch('/api/posts/toggle-mark', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ postId, roomId }),
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) {
        setPosts((prev) => prev.map((p) => (p.id === postId ? before : p)))
        alert(json?.error ?? 'マーキングに失敗しました')
        return
      }

      const updated = json?.post as
        | { id: string; is_marked: boolean; marked_by: string | null; marked_at: string | null }
        | null

      if (updated?.id) {
        setPosts((prev) =>
          prev.map((p) =>
            p.id === updated.id
              ? {
                  ...p,
                  is_marked: !!updated.is_marked,
                  marked_by: updated.marked_by ?? null,
                  marked_at: updated.marked_at ?? null,
                }
              : p
          )
        )
      } else {
        await fetchPosts()
      }
    } catch {
      setPosts((prev) => prev.map((p) => (p.id === postId ? before : p)))
      alert('通信に失敗しました')
    }
  }

  const finalPostsAll = useMemo(() => posts.filter((p) => p.post_type === 'final'), [posts])
  const logPostsAll = useMemo(() => posts.filter((p) => !p.post_type || p.post_type === 'log'), [posts])

  const applyMarkFilter = useCallback(
    (rows: PostRow[]) => {
      if (markFilter === 'marked') return rows.filter((p) => p.is_marked)
      return rows
    },
    [markFilter]
  )

  const finalPosts = applyMarkFilter(finalPostsAll)
  const logPosts = applyMarkFilter(logPostsAll)

  const renderAttachment = (p: PostRow) => {
    if (!p.attachment_url) return null

    const mime = (p.attachment_type ?? '').toLowerCase()
    const signedUrl = signedMap[p.id]

    if (!signedUrl) {
      return <div style={{ marginTop: 8, fontSize: 12, opacity: 0.7 }}>添付を読み込み中…</div>
    }

    const fileName = p.attachment_url.split('/').pop()?.split('?')[0] ?? 'download'

    if (mime.startsWith('image/')) {
      return (
        <div style={{ marginTop: 8 }}>
          <img
            src={signedUrl}
            alt={fileName}
            style={{
              maxWidth: '100%',
              borderRadius: 10,
              border: '1px solid rgba(0,0,0,0.10)',
              display: 'block',
            }}
          />
        </div>
      )
    }

    if (mime.startsWith('video/')) {
      return (
        <div style={{ marginTop: 8 }}>
          <video
            src={signedUrl}
            controls
            preload="metadata"
            style={{
              maxWidth: '100%',
              borderRadius: 10,
              border: '1px solid rgba(0,0,0,0.10)',
              display: 'block',
            }}
          />
        </div>
      )
    }

    return (
      <div
        style={{
          marginTop: 8,
          padding: 10,
          border: '1px solid rgba(0,0,0,0.10)',
          borderRadius: 10,
          background: '#fafafa',
        }}
      >
        <div style={{ fontSize: 13, fontWeight: 700 }}>{fileName}</div>
        <div style={{ fontSize: 12, opacity: 0.7, marginTop: 4 }}>
          {mime || 'application/octet-stream'}
        </div>
        <a
          href={signedUrl}
          target="_blank"
          rel="noreferrer"
          download
          style={{ display: 'inline-block', marginTop: 8, textDecoration: 'underline' }}
        >
          ダウンロード
        </a>
      </div>
    )
  }

  const showPostForms = roomStatus === 'open' && userId && memberChecked && isMember
  const showFinalForm = showPostForms && canFinal
  const showJoinHint = roomStatus === 'open' && userId && memberChecked && !isMember

  const renderMarkBadge = (p: PostRow) => {
    if (!p.is_marked) return null
